+++ b/training/level-2/L2-020-dashboard-summary/dashboardSummary.mjs
@@ -0,0 +1,53 @@
+// dashboardSummary.mjs
+
+import { validate } from 'schema-utils';
+import { join } from 'path';
+import { readFileSync } from 'fs';
+
+const schema = {
+  type: 'object',
+  properties: {
+    data: {
+      type: 'object',
+      properties: {
+        metrics: {
+          type: 'object',
+          properties: {
+            users: { type: 'integer' },
+            sessions: { type: 'integer' },
+            revenue: { type: 'number' }
+          }
+        }
+      }
+    }
+  }
+};
+
+export async function dashboardSummary(data) {
+  try {
+    validate(schema, data, {
+      name: 'Dashboard Summary Data',
+      baseDirectory: join(__dirname, '..')
+    });
+
+    const summary = {
+      metrics: {
+        users: data.metrics.users,
+        sessions: data.metrics.sessions,
+        revenue: data.metrics.revenue
+      }
+    };
+
+    // Atomic persistence
+    const summaryPath = join(__dirname, 'summary.json');
+    const summaryContent = JSON.stringify(summary, null, 2);
+
+    // Write summary to file
+    writeFileSync(summaryPath, summaryContent, 'utf-8');
+
+    return summary;
+  } catch (error) {
+    console.error('Dashboard summary validation failed:', error.message);
+    throw error;
+  }
+}

